CREATE DATABASE IF NOT EXISTS hcm_lite CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE hcm_lite;
CREATE TABLE company_settings(id INT AUTO_INCREMENT PRIMARY KEY,company_name VARCHAR(160) NOT NULL,office_start TIME NOT NULL DEFAULT '09:00:00',grace_minutes INT NOT NULL DEFAULT 15,weekend_days JSON NOT NULL DEFAULT (JSON_ARRAY(0,6)),office_lat DECIMAL(10,7),office_lng DECIMAL(10,7),office_radius_m INT DEFAULT 150,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE users(id INT AUTO_INCREMENT PRIMARY KEY,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role ENUM('admin','hr','employee') NOT NULL,employee_id INT NULL,is_active BOOLEAN NOT NULL DEFAULT TRUE,must_change_password BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE departments(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL UNIQUE);
CREATE TABLE designations(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL UNIQUE);
CREATE TABLE employees(id INT AUTO_INCREMENT PRIMARY KEY,employee_code VARCHAR(50) NOT NULL UNIQUE,full_name VARCHAR(160) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,phone VARCHAR(40),address VARCHAR(255),gender VARCHAR(30),department_id INT,designation_id INT,join_date DATE NOT NULL,status ENUM('active','probation','inactive','exited') DEFAULT 'active',exit_date DATE,basic_salary DECIMAL(12,2) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(department_id) REFERENCES departments(id),FOREIGN KEY(designation_id) REFERENCES designations(id),INDEX idx_employee_name(full_name));
ALTER TABLE users ADD CONSTRAINT fk_user_employee FOREIGN KEY(employee_id) REFERENCES employees(id);
CREATE TABLE leave_types(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(60) NOT NULL UNIQUE,annual_quota DECIMAL(6,2) NOT NULL DEFAULT 0);
INSERT INTO leave_types(name,annual_quota) VALUES('Annual',14),('Sick',8),('Casual',10),('Unpaid',0);
CREATE TABLE holidays(id INT AUTO_INCREMENT PRIMARY KEY,holiday_date DATE NOT NULL UNIQUE,title VARCHAR(160) NOT NULL);
CREATE TABLE attendance(id INT AUTO_INCREMENT PRIMARY KEY,employee_id INT NOT NULL,work_date DATE NOT NULL,check_in DATETIME,check_out DATETIME,status ENUM('present','late','half_day','absent','missing_checkout') NOT NULL,source ENUM('web','camera','hr_correction') DEFAULT 'web',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_attendance_day(employee_id,work_date),FOREIGN KEY(employee_id) REFERENCES employees(id),INDEX idx_attendance_date(work_date));
CREATE TABLE leave_requests(id INT AUTO_INCREMENT PRIMARY KEY,employee_id INT NOT NULL,leave_type_id INT NOT NULL,start_date DATE NOT NULL,end_date DATE NOT NULL,working_days DECIMAL(6,2) NOT NULL,reason TEXT,status ENUM('pending','approved','rejected','cancelled') DEFAULT 'pending',decision_comment TEXT,decided_by INT,decided_at DATETIME,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(employee_id) REFERENCES employees(id),FOREIGN KEY(leave_type_id) REFERENCES leave_types(id),FOREIGN KEY(decided_by) REFERENCES users(id),INDEX idx_leave_status(status));
CREATE TABLE payroll_runs(id INT AUTO_INCREMENT PRIMARY KEY,month TINYINT NOT NULL,year SMALLINT NOT NULL,status ENUM('draft','finalized') DEFAULT 'draft',created_by INT NOT NULL,finalized_by INT,finalized_at DATETIME,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_payroll_period(month,year),FOREIGN KEY(created_by) REFERENCES users(id),FOREIGN KEY(finalized_by) REFERENCES users(id));
CREATE TABLE payslips(id INT AUTO_INCREMENT PRIMARY KEY,payroll_run_id INT NOT NULL,employee_id INT NOT NULL,basic_salary DECIMAL(12,2),hra DECIMAL(12,2),medical DECIMAL(12,2),gross_salary DECIMAL(12,2),deductions DECIMAL(12,2),tax DECIMAL(12,2),net_salary DECIMAL(12,2),FOREIGN KEY(payroll_run_id) REFERENCES payroll_runs(id),FOREIGN KEY(employee_id) REFERENCES employees(id),UNIQUE KEY uq_run_employee(payroll_run_id,employee_id));
CREATE TABLE announcements(id INT AUTO_INCREMENT PRIMARY KEY,title VARCHAR(180) NOT NULL,message TEXT NOT NULL,created_by INT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(created_by) REFERENCES users(id));
CREATE TABLE notifications(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,title VARCHAR(180) NOT NULL,message TEXT NOT NULL,is_read BOOLEAN DEFAULT FALSE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE audit_logs(id BIGINT AUTO_INCREMENT PRIMARY KEY,actor_user_id INT,action VARCHAR(80) NOT NULL,entity VARCHAR(80) NOT NULL,entity_id BIGINT,before_json JSON,after_json JSON,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(actor_user_id) REFERENCES users(id),INDEX idx_audit_created(created_at));
